using System.Net.Http; using System.Threading; using System.Threading.Tasks; using System.Net; namespace CloudClient; public sealed class SessionHandler:DelegatingHandler { readonly Action expired; int fired; public SessionHandler(Action expired):base(new HttpClientHandler()){this.expired=expired;} protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancellationToken){var response=await base.SendAsync(request,cancellationToken);if(response.StatusCode==HttpStatusCode.Unauthorized&&Interlocked.Exchange(ref fired,1)==0)expired();return response;} }